export default function New_Dish() {
  return (
    <View className="py-4">
      <View className="flex-row items-center justify-between">
        <Text className="text-2xl font-bold text-[#2D2D2D] mb-4">
          Món mới ra mắt <Text className="text-[#E07B39]">NEW</Text>
        </Text>
        <TouchableOpacity className="bg-[#E07B39] p-2 rounded-full mb-5">
          <MaterialCommunityIcons name="arrow-right" size={24} color="black" />
        </TouchableOpacity>
      </View>
      <View>
        <FlatList
          data={List_New_Dish.slice(0, 6)}
          horizontal
          showsHorizontalScrollIndicator={false}
          keyExtractor={(item) => item.id.toString()}
          renderItem={({ item }) => (
            <TouchableOpacity className="mr-4">
              <View className="bg-white rounded-2xl w-[180px] border border-[#E5D5C3] shadow-sm overflow-hidden">
                <Image
                  source={{ uri: item.image }}
                  className="w-full h-[120px]"
                  resizeMode="cover"
                />
                <View className="p-3">
                  <Text
                    numberOfLines={2}
                    className="text-sm font-bold text-[#2D2D2D] mb-1 h-[36px]"
                  >
                    {item.name}
                  </Text>
                  <Text className="text-xs text-[#6B4423] mb-2">
                    {item.category}
                  </Text>
                  <View className="flex-row items-center justify-between">
                    <Text className="text-base font-bold text-[#E07B39]">
                      {item.price}
                    </Text>
                    <TouchableOpacity className="bg-[#E07B39] p-1 rounded-full">
                      <MaterialCommunityIcons
                        name="plus"
                        size={20}
                        color="white"
                      />
                    </TouchableOpacity>
                  </View>
                </View>
              </View>
            </TouchableOpacity>
          )}
        />
      </View>
    </View>
  );
}
